var i=`0857-rajma`;var t=`world-0857`;var a=`IN`;var s=`south-asia`;var o=4;var r=618;var g={en:`Rajma`,ua:`Раджма`};var l={en:`Rajma is a India dish made with kidney beans, yellow onion, tomato, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Раджма, страва кухні країни Індія. Основні складники: червона квасоля кідні, жовта цибуля, помідор, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Soak dried legumes in plenty of cool water for 480 minutes, then drain and discard the soaking water. Cook them fully in fresh water.`,ua:`Замочіть сухі бобові у великій кількості прохолодної води на 480 хвилин, потім злийте та вилийте воду від замочування. Повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:480,i:[[`kidney-beans`,370,`g`],[`water`,1200,`ml`]]},{en:`After discarding soaking water, boil kidney beans vigorously for at least 10 minutes and then simmer until thoroughly soft; never slow-cook uncooked kidney beans alone.`,ua:`Після зливання води від замочування інтенсивно кип’ятіть квасолю не менше 10 хвилин, потім варіть до повної м’якості; не готуйте сиру квасолю тільки на слабкому нагріванні.`,t:[`boiling`],m:95,i:[[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,200,`g`],[`tomato`,340,`g`],[`ginger-garlic-paste`,30,`g`],[`ghee`,45,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 28 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 28 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:28,i:[[`garam-masala`,7,`g`],[`ground-cumin`,6,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`]]}];var m={slug:i,id:t,country:`IN`,region:s,servings:4,minutes:618,title:g,text:l,steps:d};export{a as country,m as default,t as id,r as minutes,s as region,o as servings,i as slug,d as steps,l as text,g as title};